import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import './Service.css';

const Service = () => {
    const [servicePage, setServicePage] = useState(null);
    const navigate = useNavigate();

    useEffect(() => {
        fetch('http://localhost:3001/pages/6', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({})
        })
            .then(response => response.json())
            .then(page => setServicePage(page))
            .catch(error => console.error('Error fetching data:', error));
    }, []);

    const doLoginAndGetAccessToken = async () => {
        debugger
        const server_url = 'https://plus.trackimo.com';
        const client_id = '9092cd94-a728-47b7-86da-e15c9a3d4cdb';
        const client_secret = '9f540cd42ec8d3bc452ce39cdd3d6de4';
        const user_name = 'koko.hamdi123@gmail.com';
        const password = 'Test@1234';
        const redirect_uri = 'https://plus.trackimo.com/api/internal/v1/oauth_redirect';

        try {
            console.log('Logging in...');
            const loginResponse = await axios.post(`${server_url}/api/internal/v2/user/login`, {
                username: user_name,
                password: password
            }, {
                headers: { 'Content-Type': 'application/json' },
                withCredentials:true

            });
                if(loginResponse.status !== 200){
                    console.log('LOgin failed')
                }
            console.log('Login response:', loginResponse);

            // const cookies = loginResponse.headers['set-cookie'];
            // if (!cookies) {
            //     throw new Error('No cookies set during login');
            // }

            console.log('Logged in. Fetching auth code...');
            const authResponse = await axios.get(`${server_url}/api/v3/oauth2/auth`, {
                params: {
                    client_id: client_id,
                    redirect_uri: redirect_uri,
                    response_type: 'code',
                    scope: 'locations,notifications,devices,accounts,settings,geozones'
                },
                headers: { 'Cookie': cookies.join(';') },
                withCredentials: true,
                maxRedirects: 0,
                validateStatus: status => status === 302
            });

            const location = authResponse.headers.location;
            const code = location.split('=')[1];

            console.log('Auth code received. Fetching access token...');
            const tokenResponse = await axios.post(`${server_url}/api/v3/oauth2/token`, {
                client_id: client_id,
                client_secret: client_secret,
                code: code
            }, {
                headers: { 'Content-Type': 'application/json', 'Cookie': cookies.join(';') },
                withCredentials: true
            });

            console.log('Access token received:', tokenResponse.data.access_token);
            return tokenResponse.data.access_token;
        } catch (error) {
            console.error('Error during login and getting access token:', error);
            throw error;
        }
    };

    const askDeviceToSendLocation = async (accessToken, accountId, deviceId) => {
        const server_url = 'https://plus.trackimo.com';

        try {
            console.log('Requesting device location...');
            const response = await axios.post(`${server_url}/api/v3/accounts/${accountId}/devices/ops/getLocation`, {
                devices: [deviceId],
                forceGpsRead: true,
                sendGsmBeforeLock: true
            }, {
                headers: {
                    'Authorization': `Bearer ${accessToken}`,
                    'Content-Type': 'application/json'
                },
                withCredentials: true
            });

            console.log('Location data received:', response.data);
            return response.data;
        } catch (error) {
            console.error('Error sending location request to device:', error);
            throw error;
        }
    };

    if (!servicePage) return <div>PAGE NOT FOUND</div>;

    const contentService = servicePage.content;

    return (
        <div className="container">
            <div className="image-section"></div>
            <div className="paw"></div>
            <div className="content-section">
                <p className="Hello">{contentService && contentService[0]}</p>
                <p className="Miss">{contentService && contentService[1]}</p>
                <button className="location" onClick={async () => {
                    debugger
                    try {
                        console.log('Handling location click...');
                        const accessToken = await doLoginAndGetAccessToken();
                        const accountId = '362279607'; // Replace with actual account ID
                        const deviceId = '8621'; // Replace with actual device ID
                        const locationData = await askDeviceToSendLocation(accessToken, accountId, deviceId);

                        const petLocation = {
                            lat: locationData.latitude,
                            lng: locationData.longitude
                        };

                        console.log('Navigating to Map with location:', petLocation);
                        navigate('/Map', { state: { location: petLocation } });
                    } catch (error) {
                        console.error('Error fetching pet location:', error);
                    }
                }}>
                    Pet's Location
                </button>
            </div>
        </div>
    );
};

export default Service;
